def to_goat_latin(sentence):
    answer=[]
    for index,word in enumerate(sentence.split(),1):
        if word[0].lower() not in 'aeiou':word=word[1:]+word[0]
        answer.append(word+'ma'+'a'*index)
    return ' '.join(answer)

